use serde_json::{Value, from_str};

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let pairs: Vec<(i64, i64)> = from_str(&input.to_string()).unwrap();
    let mut sorted_pairs = pairs.clone();
    sorted_pairs.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
    serde_json::to_value(sorted_pairs).unwrap()
}
